create table rmais_users (
    user_id         number,
    user_name       varchar2(255 byte) not null enable,
    status          char(1 byte) default 'Y' not null enable,
    creation_date   timestamp(6) default systimestamp not null enable,
    created_by      varchar2(128 byte) not null enable,
    updated_date    timestamp(6) default systimestamp not null enable,
    updated_by      varchar2(128 byte) not null enable,
    inactive_date   timestamp(6),
    email           varchar2(100 byte),
    phone           number,
    password        varchar2(255 byte),
    change_pwd_flag char(1 byte) default 'N',
    first_name      varchar2(55 byte) not null enable,
    last_name       varchar2(55 byte) not null enable
);

alter table rmais_users
    add constraint chk_rmais_users_status
        check ( status in ( 'Y', 'N' ) ) enable;

alter table rmais_users
    add constraint pk_rmais_users primary key ( user_id )
        using index enable;


